// Presentation only: no cards, stats, formation or save data in this module.
const duration=ms=>matchMedia('(prefers-reduced-motion: reduce)').matches?1:ms;
const roller=new Image();roller.src='assets/tabletop/scroll.png';
const animated=new Set();let locked=false;
export const isTableTransition=()=>locked;
export function closedRollTravel(height,rodHeight){return Math.max(0,height/2-rodHeight*.87+1);}
function paint(){if(!roller.naturalWidth)return;document.querySelectorAll('.table-rod').forEach(el=>{const c=el.firstElementChild,w=el.clientWidth,h=el.clientHeight;if(!w||!h)return;const d=Math.min(devicePixelRatio||1,2);c.width=w*d;c.height=h*d;const g=c.getContext('2d');g.scale(d,d);const sw=roller.naturalWidth,sh=roller.naturalHeight,cap=sw*.17,end=Math.min(w*.18,h*.85);g.drawImage(roller,0,sh*.2,cap,sh*.57,0,0,end,h);g.drawImage(roller,cap,sh*.2,sw-2*cap,sh*.57,end,0,w-2*end,h);g.drawImage(roller,sw-cap,sh*.2,cap,sh*.57,w-end,0,end,h);});}
roller.onload=paint;window.addEventListener('resize',paint);
export function mountParchment(root){const surface=document.createElement('div');surface.className='paper-surface';surface.append(...root.childNodes);root.append(surface);for(const name of ['top','bottom']){const rod=document.createElement('div');rod.className='table-rod '+name;rod.setAttribute('aria-hidden','true');rod.append(document.createElement('canvas'));root.append(rod);}requestAnimationFrame(paint);}
export function mountLeather(root){if(root.querySelector('.leather-surface'))return;const surface=document.createElement('div');surface.className='leather-surface';surface.append(...root.childNodes);const curl=document.createElement('div');curl.className='leather-curl';curl.setAttribute('aria-hidden','true');curl.hidden=true;root.append(surface,curl);}
async function animate(el,frames,ms){const a=el.animate(frames,{duration:duration(ms),easing:'cubic-bezier(.65,0,.25,1)',fill:'forwards'});animated.add(a);await a.finished;Object.assign(el.style,frames.at(-1));a.cancel();animated.delete(a);}
function setClosed(root,type,closed){if(type==='map'){root.querySelector('.paper-surface').style.clipPath=closed?'inset(50% 0 50% 0)':'inset(0)';const rods=root.querySelectorAll('.table-rod'),d=closedRollTravel(root.clientHeight,rods[0].offsetHeight);rods.forEach((r,i)=>r.style.transform=closed?`translateY(${i?-d:d}px)`:'translateY(0)');paint();}else{root.querySelector('.leather-surface').style.clipPath=closed?'inset(0 0 100% 0)':'inset(0)';const curl=root.querySelector('.leather-curl');curl.hidden=!closed;curl.style.top='0%';}}
async function roll(root,type,closing){if(type==='map'){const rods=[...root.querySelectorAll('.table-rod')],d=closedRollTravel(root.clientHeight,rods[0].offsetHeight),v=closing?[0,1]:[1,0];await Promise.all([animate(root.querySelector('.paper-surface'),v.map(p=>({clipPath:`inset(${p*50}% 0 ${p*50}% 0)`})),850),...rods.map((r,i)=>animate(r,v.map(p=>({transform:`translateY(${p*d*(i?-1:1)}px)`})),850))]);}else{const curl=root.querySelector('.leather-curl');curl.hidden=false;const v=closing?[0,1]:[1,0];await Promise.all([animate(root.querySelector('.leather-surface'),v.map(p=>({clipPath:`inset(0 0 ${p*100}% 0)`})),1000),animate(curl,v.map(p=>({top:`clamp(0px, calc(${(1-p)*100}% - var(--curl-height)/2), calc(100% - var(--curl-height)))`})),1000)]);curl.hidden=!closing;}setClosed(root,type,closing);}
export async function switchTable(from,to,fromType,toType,prepare){if(locked)return false;locked=true;from.inert=true;to.inert=true;document.body.classList.add('table-transition');let completed=false;try{await roll(from,fromType,true);await animate(from,[{transform:'translateX(0)'},{transform:'translateX(-120vw)'}],480);from.hidden=true;await prepare();to.style.transform='translateX(120vw)';to.hidden=false;setClosed(to,toType,true);await animate(to,[{transform:'translateX(120vw)'},{transform:'translateX(0)'}],480);await roll(to,toType,false);completed=true;return true;}finally{for(const a of animated)a.cancel();animated.clear();from.style.transform='';to.style.transform='';from.hidden=completed;to.hidden=!completed;setClosed(completed?to:from,completed?toType:fromType,false);from.inert=false;to.inert=false;locked=false;document.body.classList.remove('table-transition');}}
